xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        W := 0.5;
        R := W * 0.33;

        N := 16; // must be 4 * k
        M := 16;

        tn := tan(Pi / N);
        s2 := sqrt(2);
        if N mod 8 = 4 then
          s2 := s2 * cos(Pi / N);

        for i := 0 to M - 1 do begin
            Vx[i] := W - R - R * cos(2*Pi * i / M);
            Vz[i] := W - R - R * sin(2*Pi * i / M);
            Vy[i] := Vx[i] * tn;
            Vt[i] :=-Vy[i];

            // find exact corner's coordinates, intersection with z - x / s2 = 0
            if (i > 0) then begin
                Z1 := Vz[i - 1];
                F1 := Z1 - Vx[i - 1] / s2;
                Z2 := Vz[i];
                F2 := Z2 - Vx[i] / s2;

                if F2 > 0 then
                    if F1 < 0 then
                        D := Z1 - F1 * (Z2 - Z1) / (F2 - F1); 
            end;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;
        idx1 := FromTo( 0, M - 1);
        idx2 := FromTo( 2 * M - 1, M);

Macro.Script:
i1 := i;
i2 := (i + 1) mod M;
Inc(i);
